'use client';

import { useState } from 'react';

import { Sheet, SheetContent, SheetTitle } from '@/registry/ndeko/ui/sheet';

import { ConversationSidebar } from './conversation-list';
import { ConversationView } from './conversation-view';
import {
  NEW_CHAT_TITLE,
  TITLE_WORD_LIMIT,
  newChatReplies,
  reader,
  seedConversations,
  type Conversation,
} from './data';

function titleOf(text: string) {
  const words = text.trim().split(/\s+/);
  const shown = words.slice(0, TITLE_WORD_LIMIT);
  return shown.join(' ');
}

function isListed(conversation: Conversation) {
  return !conversation.isDraft;
}

function namedConversation(
  conversation: Conversation,
  conversationId: string,
  title: string
): Conversation {
  if (conversation.id !== conversationId) {
    return conversation;
  }
  return { ...conversation, title, isDraft: false };
}

function draftOf(draftNumber: number): Conversation {
  return {
    id: `chat-${draftNumber}`,
    title: NEW_CHAT_TITLE,
    turns: [],
    replies: newChatReplies,
    isDraft: true,
  };
}

export default function Application05() {
  const [conversations, setConversations] =
    useState<Conversation[]>(seedConversations);
  const [activeId, setActiveId] = useState(seedConversations[0].id);
  const [draftCount, setDraftCount] = useState(0);
  const [isNavigationOpen, setIsNavigationOpen] = useState(false);
  const listedConversations = conversations.filter(isListed);

  function openConversation(conversationId: string) {
    setActiveId(conversationId);
    setIsNavigationOpen(false);
  }

  function startNewChat() {
    setIsNavigationOpen(false);
    const openDraft = conversations.find(
      (conversation) => conversation.isDraft
    );
    if (openDraft) {
      setActiveId(openDraft.id);
      return;
    }
    const draftNumber = draftCount + 1;
    const draft = draftOf(draftNumber);
    setDraftCount(draftNumber);
    setConversations((current) => [draft, ...current]);
    setActiveId(draft.id);
  }

  function nameConversation(conversationId: string, titleSource: string) {
    const title = titleOf(titleSource);
    setConversations((current) =>
      current.map((conversation) =>
        namedConversation(conversation, conversationId, title)
      )
    );
  }

  function openNavigation() {
    setIsNavigationOpen(true);
  }

  const sidebarProps = {
    conversations: listedConversations,
    activeId,
    person: reader,
    onSelect: openConversation,
    onNewChat: startNewChat,
  };

  return (
    <div className='bg-sidebar text-foreground flex h-dvh min-h-[30rem] w-full md:p-2'>
      <aside
        aria-label='Conversations'
        className='hidden w-64 shrink-0 pr-2 md:block'
      >
        <ConversationSidebar {...sidebarProps} />
      </aside>
      <Sheet open={isNavigationOpen} onOpenChange={setIsNavigationOpen}>
        <SheetContent
          side='left'
          showCloseButton={false}
          className='bg-sidebar w-72 gap-0 p-2'
        >
          <SheetTitle className='sr-only'>Conversations</SheetTitle>
          <ConversationSidebar {...sidebarProps} />
        </SheetContent>
      </Sheet>
      <main className='bg-background md:hairline-ring md:ring-border flex min-w-0 flex-1 flex-col overflow-clip md:rounded-xl md:shadow-[0_1px_2px_rgb(0_0_0/0.04)]'>
        {conversations.map((conversation) => (
          <div
            key={conversation.id}
            hidden={conversation.id !== activeId}
            className='flex min-h-0 flex-1 flex-col'
          >
            <ConversationView
              conversation={conversation}
              onFirstMessage={nameConversation}
              onOpenNavigation={openNavigation}
            />
          </div>
        ))}
      </main>
    </div>
  );
}

'use client';

import { AnimatePresence, motion, useReducedMotion } from 'motion/react';
import { useId } from 'react';

import {
  FeatherIcon,
  MessageCircleIcon,
  PlusIcon,
} from '@/registry/ndeko/lib/icons';
import { Button } from '@/registry/ndeko/ui/button';

import { AccountMenu } from './account-menu';
import { PRODUCT_NAME, type Conversation, type Person } from './data';
import { revealVariantsOf } from './presence';
import { ActiveRowIndicator, NAV_ROW, ariaCurrentOf } from './sidebar-parts';

export function QuillstoneMark() {
  return (
    <span
      aria-hidden='true'
      className='gem-plate inline-flex size-6 shrink-0 items-center justify-center rounded-md [--gem:var(--primary)] [&_svg]:size-3.5'
    >
      <FeatherIcon />
    </span>
  );
}

type ConversationRowProps = {
  conversation: Conversation;
  isActive: boolean;
  indicatorId: string;
  onSelect: (conversationId: string) => void;
};

function ConversationRow({
  conversation,
  isActive,
  indicatorId,
  onSelect,
}: ConversationRowProps) {
  const shouldReduceMotion = useReducedMotion();
  const variants = revealVariantsOf(shouldReduceMotion);
  const ariaCurrent = ariaCurrentOf(isActive);

  function select() {
    onSelect(conversation.id);
  }

  return (
    <motion.li
      variants={variants}
      initial='hidden'
      animate='shown'
      exit='hidden'
    >
      <button
        type='button'
        aria-current={ariaCurrent}
        onClick={select}
        className={NAV_ROW}
      >
        {isActive && <ActiveRowIndicator layoutId={indicatorId} />}
        <MessageCircleIcon />
        <span className='relative min-w-0 flex-1 truncate'>
          {conversation.title}
        </span>
      </button>
    </motion.li>
  );
}

type ConversationSidebarProps = {
  conversations: Conversation[];
  activeId: string;
  person: Person;
  onSelect: (conversationId: string) => void;
  onNewChat: () => void;
};

export function ConversationSidebar({
  conversations,
  activeId,
  person,
  onSelect,
  onNewChat,
}: ConversationSidebarProps) {
  const indicatorId = useId();

  return (
    <div className='flex h-full min-h-0 flex-col gap-3'>
      <div className='flex flex-col gap-2'>
        <div className='flex h-9 items-center gap-2 px-1.5'>
          <QuillstoneMark />
          <span className='text-[13px] font-semibold'>{PRODUCT_NAME}</span>
        </div>
        <Button
          variant='outline'
          onClick={onNewChat}
          className='w-full justify-start'
        >
          <PlusIcon />
          New chat
        </Button>
      </div>
      <nav
        aria-label='Conversations'
        className='-mx-2 flex min-h-0 flex-1 flex-col gap-0.5 overflow-y-auto px-2'
      >
        <p className='text-muted-foreground flex h-6 items-center px-2 text-xs font-medium'>
          Recent
        </p>
        <ul className='flex flex-col'>
          <AnimatePresence initial={false}>
            {conversations.map((conversation) => (
              <ConversationRow
                key={conversation.id}
                conversation={conversation}
                isActive={conversation.id === activeId}
                indicatorId={indicatorId}
                onSelect={onSelect}
              />
            ))}
          </AnimatePresence>
        </ul>
      </nav>
      <AccountMenu person={person} />
    </div>
  );
}

'use client';

import { motion, type Transition, useReducedMotion } from 'motion/react';

import {
  Avatar,
  AvatarFallback,
  AvatarImage,
} from '@/registry/ndeko/ui/avatar';

import type { Person } from './data';

export const NAV_ROW = [
  'relative flex h-7 w-full min-w-0 items-center gap-2 rounded-md px-2 text-left text-[13px] font-medium text-foreground outline-none',
  'transition-colors duration-150 hover:bg-foreground/5 focus-visible:ring-[3px] focus-visible:ring-ring/25',
  "[&_svg]:pointer-events-none [&_svg]:relative [&_svg]:shrink-0 [&_svg:not([class*='size-'])]:size-4 [&_svg:not([class*='text-'])]:text-muted-foreground",
].join(' ');

const INDICATOR_TRAVEL: Transition = {
  duration: 0.25,
  ease: [0.77, 0, 0.175, 1],
};

const INSTANT: Transition = { duration: 0 };

function travelOf(shouldReduceMotion: boolean | null) {
  if (shouldReduceMotion) {
    return INSTANT;
  }
  return INDICATOR_TRAVEL;
}

/** The one highlight of the active row. It travels from the old row to the new one. */
export function ActiveRowIndicator({ layoutId }: { layoutId: string }) {
  const shouldReduceMotion = useReducedMotion();

  return (
    <motion.span
      aria-hidden='true'
      layoutId={layoutId}
      transition={travelOf(shouldReduceMotion)}
      className='bg-foreground/[0.07] absolute inset-0 rounded-md'
    />
  );
}

export function PersonAvatar({
  person,
  className,
}: {
  person: Person;
  className?: string;
}) {
  return (
    <Avatar className={className}>
      {person.avatar && <AvatarImage src={person.avatar} alt='' />}
      <AvatarFallback>{person.initials}</AvatarFallback>
    </Avatar>
  );
}

export function ariaCurrentOf(isActive: boolean) {
  if (isActive) {
    return 'page' as const;
  }
  return undefined;
}

